<script setup>
import { computed, ref } from 'vue';
import { useForm, usePage } from '@inertiajs/vue3';
import B from '../Components/SynauxButton.vue';
import F from '../Components/SynauxField.vue';
import T from '../Components/SynauxTitle.vue';
import S from '../Components/SynauxStatus.vue';
import E from '../Components/SynauxEmpty.vue';
import RequestForm from '../Components/SynauxRequestForm.vue';
import { money, date, useSubmit } from '../support/synaux';
// Las colecciones llegan filtradas por el servidor; el navegador solo organiza búsquedas y presentación.
const props = defineProps({ data: Object });
const page = usePage();
const submit = useSubmit();
const search = ref('');
const status = ref('');
const decision = ref(props.data.referenceKey === 'presupuesto-aceptar' ? 'accepted' : props.data.referenceKey === 'presupuesto-rechazar' ? 'rejected' : '');
const section = computed(() => props.data.screen === 'cliente' ? props.data.section || 'resumen' : props.data.screen);
const record = computed(() => props.data.selected ?? {});
const requests = computed(() => props.data.requests ?? []);
const quotes = computed(() => props.data.quotes ?? []);
const projects = computed(() => props.data.projects ?? []);
const estimates = computed(() => props.data.estimates ?? []);
const collections = computed(() => ({solicitudes:requests.value,presupuestos:quotes.value,proyectos:projects.value,estimaciones:estimates.value}));
const rows = computed(() => (collections.value[section.value] ?? []).filter(r => (!search.value || `${r.title ?? r.summary} ${r.id}`.toLowerCase().includes(search.value.toLowerCase())) && (!status.value || (r.display_status ?? r.status) === status.value)));
const titles = {resumen:'Tu espacio en Synaux',estimaciones:'Mis estimaciones',solicitudes:'Mis solicitudes',presupuestos:'Mis presupuestos',proyectos:'Mis proyectos',solicitud:'Detalle de solicitud',proyecto:'Tu proyecto',presupuesto:'Presupuesto formal'};
const stateForm = useForm({id:record.value.id,status:'closed'});
const decideForm = useForm({id:record.value.id,decision:'',confirmed:false});
const versions = computed(() => quotes.value.filter(q => q.budget_id === record.value.budget_id));
const canDecide = computed(() => record.value.status === 'sent' && record.value.display_status !== 'expired' && record.value.current && (props.data.preview || record.value.request_owner === page.props.auth?.id || record.value.client_user_id === page.props.auth?.id));
function decide() { decideForm.decision = decision.value; submit(decideForm,'decidir-presupuesto',{previewTarget:decision.value === 'accepted' ? 'proyecto' : 'presupuestos'}); }
function closeRequest() { submit(stateForm,'estado-solicitud'); }
function href(row) { return `/${{solicitudes:'solicitudes',presupuestos:'presupuestos',proyectos:'proyectos',estimaciones:'estimaciones'}[section.value]}/${row.id}`; }
</script>
<template>
    <section :class="['page shell', {narrow:['solicitud','presupuesto','proyecto'].includes(section)}]">
        <!-- El resumen conserva los accesos y el orden de actividad del prototipo, con conteos persistentes. -->
        <template v-if="section === 'resumen'"><T eyebrow="Área cliente" :title="`Hola, ${$page.props.auth?.name?.split(' ')[0] ?? 'Martina'}`" description="Revisá tus solicitudes, presupuestos y proyectos en un solo lugar."><B href="/solicitudes/nueva" arrow>Nueva solicitud</B></T><div class="stats-grid"><v-card v-for="[label,value,link] in [['Estimaciones',estimates.length,'estimaciones'],['Solicitudes',requests.length,'solicitudes'],['Presupuestos',quotes.length,'presupuestos'],['Proyectos',projects.length,'proyectos']]" :key="label" class="card stat"><span>{{ label }}</span><strong>{{ value }}</strong><B variant="ghost" :href="`/cliente/${link}`">Ver {{ label.toLowerCase() }} →</B></v-card></div><div class="detail-layout"><v-card class="card"><div class="section-head"><h2>Actividad reciente</h2><B variant="ghost" href="/cliente/solicitudes">Ver todas</B></div><div v-for="r in requests.slice(0,3)" :key="r.id" class="list-row"><div><small>SOL-{{ r.id }} · {{ date(r.created_at) }}</small><h3>{{ r.title }}</h3><S :status="r.status" /></div><B :href="`/solicitudes/${r.id}`" variant="secondary">Ver detalle</B></div><E v-if="!requests.length" title="Todavía no tenés solicitudes" text="Empezá contando qué necesitás resolver." /></v-card><aside><v-card class="card soft-panel"><p class="eyebrow">Tu próximo paso</p><h3>De la idea al proyecto</h3><p>Estimá el alcance, creá una solicitud y revisá la propuesta formal antes de confirmar.</p><B href="/estimador" arrow>Estimar un proyecto</B></v-card></aside></div></template>
        <!-- Los listados comparten filtros; cada tarjeta conduce a su propio registro autorizado. -->
        <template v-else-if="['estimaciones','solicitudes','presupuestos','proyectos'].includes(section)"><T eyebrow="Área cliente" :title="titles[section]" description="Consultá el estado y los próximos pasos de cada proyecto."><B v-if="section === 'solicitudes'" href="/solicitudes/nueva" arrow>Nueva solicitud</B><B v-if="section === 'estimaciones'" href="/estimador" arrow>Nueva estimación</B></T><div class="filters"><F v-model="search" label="Buscar" placeholder="Título o identificador" /><F v-model="status" label="Estado" type="select" :options="[{value:'',label:'Todos'},{value:'draft',label:'Borrador'},{value:'open',label:'Enviada'},{value:'sent',label:'Enviado'},{value:'accepted',label:'Aceptado'},{value:'expired',label:'Vencido'},{value:'in_progress',label:'En curso'},{value:'completed',label:'Completado'}]" /></div><div class="stack"><v-card v-for="r in rows" :key="r.id" class="card list-row"><div><small>{{ {estimaciones:'EST',solicitudes:'SOL',presupuestos:'PRE',proyectos:'PRY'}[section] }}-{{ r.id }} · {{ date(r.created_at) }}</small><h3>{{ r.title ?? r.summary }}</h3><p>{{ r.service_name ?? (section === 'presupuestos' ? `Versión ${r.version_number} · ${money(r.total,r.currency_code)}` : section === 'estimaciones' ? `${money(r.price_min,r.currency_snapshot)}${r.price_max != null ? ` – ${money(r.price_max,r.currency_snapshot)}` : ''}` : '') }}</p><S :status="r.display_status ?? r.status" /></div><B :href="href(r)" variant="secondary">{{ r.status === 'draft' && section === 'solicitudes' ? 'Continuar borrador' : 'Ver detalle' }}</B></v-card></div><E v-if="!rows.length" :title="search || status ? 'No encontramos resultados' : `Todavía no tenés ${section}`" text="Cuando haya actividad, aparecerá acá con su estado actualizado." :href="section === 'estimaciones' ? '/estimador' : '/solicitudes/nueva'" action="Crear una nueva solicitud" /></template>
        <template v-else-if="section === 'solicitud' && record.status === 'draft'"><T eyebrow="Solicitud en borrador" :title="record.title" description="Podés completar y revisar la información antes de enviarla." /><RequestForm :data="data" /></template>
        <template v-else-if="section === 'solicitud'"><B variant="ghost" href="/cliente/solicitudes">← Volver a solicitudes</B><T :eyebrow="`SOL-${record.id} · Solicitud`" :title="record.title"><S :status="record.status" /></T><div class="detail-layout"><v-card class="card"><h2>Sobre tu solicitud</h2><p class="preserve-lines">{{ record.description }}</p><dl class="data-list"><div><dt>Servicio</dt><dd>{{ record.service_name }}</dd></div><div><dt>Visibilidad</dt><dd>{{ record.visibility === 'public' ? 'Pública' : 'Privada' }}</dd></div><div><dt>Fecha de envío</dt><dd>{{ date(record.created_at) }}</dd></div><div><dt>Revisión</dt><dd>{{ record.reviewed_at ? date(record.reviewed_at) : 'Pendiente de revisión' }}</dd></div></dl><h3 v-if="record.answers?.length">Respuestas de la estimación</h3><dl class="data-list"><div v-for="a in record.answers" :key="a.id"><dt>{{ a.question }}</dt><dd>{{ a.label }}</dd></div></dl></v-card><aside><v-card class="card soft-panel"><h3>¿Qué sigue?</h3><template v-if="data.area === 'gestion'"><p>Revisá el alcance y las respuestas del cliente para preparar la propuesta formal.</p><B v-if="record.status === 'open'" :href="'/editor/presupuesto?solicitud=' + record.id" arrow>Preparar presupuesto</B><B href="/gestion/solicitudes" variant="secondary">Volver a Gestión</B></template><template v-else-if="record.visibility === 'private' || !$page.props.stageTwo"><p>Synaux revisará tu pedido y preparará un presupuesto con el alcance, el importe y los plazos.</p><B href="/cliente/presupuestos" variant="secondary">Consultar presupuestos</B></template><template v-else><p>Podés consultar las propuestas recibidas e invitar profesionales para tu proyecto.</p><B href="/cliente/propuestas" variant="secondary">Ver propuestas</B><B href="/profesionales" variant="ghost">Buscar profesionales</B></template></v-card><v-card v-if="record.status === 'open'" class="card"><h3>Gestionar solicitud</h3><p>Podés cerrarla si ya no necesitás continuar con el pedido.</p><B variant="secondary" :disabled="stateForm.processing" @click="closeRequest">Cerrar solicitud</B></v-card></aside></div></template>
        <!-- La decisión exige confirmar una versión vigente. Las anteriores quedan consultables en el historial. -->
        <template v-else-if="section === 'presupuesto'"><B href="/cliente/presupuestos" variant="ghost">← Volver a presupuestos</B><T :eyebrow="`PRE-${record.budget_id} · Presupuesto formal`" :title="record.title" :description="`Versión ${record.version_number} · Emitida el ${date(record.sent_at ?? record.created_at)}`"><S :status="record.display_status ?? record.status" /></T><div class="detail-layout"><div class="stack"><v-card class="card"><div class="section-head"><h2>Alcance y conceptos</h2><span>Moneda: {{ record.currency_code }}</span></div><div class="table-scroll"><table><thead><tr><th>Concepto</th><th>Cant.</th><th>Subtotal</th></tr></thead><tbody><tr v-for="(item,index) in record.items" :key="index"><td>{{ item.description }}</td><td>{{ item.quantity }}</td><td>{{ money(item.quantity * item.unit_price,record.currency_code) }}</td></tr></tbody></table></div><dl class="data-list"><div><dt>Subtotal</dt><dd>{{ money(record.subtotal,record.currency_code) }}</dd></div><div><dt>Impuestos ({{ record.tax_rate }}%)</dt><dd>{{ money(record.total-record.subtotal,record.currency_code) }}</dd></div><div class="total"><dt>Total final</dt><dd>{{ money(record.total,record.currency_code) }}</dd></div></dl></v-card><v-card class="card"><h2>Plazos y condiciones</h2><dl class="data-list"><div><dt>Plazo estimado</dt><dd>{{ record.estimated_delivery_days }} días desde el inicio</dd></div><div><dt>Vigencia</dt><dd>Hasta el {{ date(record.valid_until) }}</dd></div></dl><p class="preserve-lines">{{ record.terms }}</p><p>Los pagos se coordinan entre las partes y no se procesan en esta plataforma.</p></v-card></div><aside><v-card class="card soft-panel"><h3>Historial</h3><div v-for="v in versions" :key="v.id" class="version-entry"><B :href="`/presupuestos/${v.id}`" variant="ghost">Versión {{ v.version_number }}</B><S :status="v.display_status ?? v.status" /><small>{{ date(v.sent_at ?? v.created_at) }}</small></div></v-card><v-card v-if="canDecide" class="card"><h3>Tu decisión</h3><p>Confirmá que revisaste alcance, total, plazo y condiciones.</p><div class="button-stack"><B @click="decision = 'accepted'">Aceptar presupuesto</B><B variant="ghost" @click="decision = 'rejected'">Rechazar</B></div></v-card><v-card v-else class="card"><h3>{{ record.display_status === 'expired' ? 'Presupuesto vencido' : 'Estado de esta versión' }}</h3><p>{{ record.display_status === 'expired' ? 'La vigencia finalizó. Solicitá una nueva versión antes de confirmar.' : record.current ? 'Podés consultar el documento y su estado.' : 'Hay una versión más reciente. Consultala antes de decidir.' }}</p><B v-if="record.issuer_id === $page.props.auth?.id || data.area === 'gestion' || data.area === 'profesional'" :href="`/editor/presupuesto/${record.id}`" variant="secondary">Preparar nueva versión</B></v-card></aside></div></template>
        <template v-else-if="section === 'proyecto'"><B href="/cliente/proyectos" variant="ghost">← Volver a proyectos</B><T :eyebrow="`PRY-${record.id} · Proyecto`" :title="record.title"><S :status="record.status" /></T><div class="detail-layout"><v-card class="card"><h2>Avance del proyecto</h2><div class="section-head"><span>Progreso general</span><strong>{{ record.progress }}%</strong></div><progress max="100" :value="record.progress" /><dl class="data-list"><div><dt>Inicio</dt><dd>{{ date(record.start_date) }}</dd></div><div><dt>Finalización</dt><dd>{{ date(record.end_date) }}</dd></div></dl><h3>Última actualización</h3><p class="preserve-lines">{{ record.notes || 'El profesional registrará los avances y próximos pasos acá.' }}</p></v-card><aside><v-card class="card soft-panel"><h3>Presupuesto aceptado</h3><p>La contratación conserva la versión y condiciones que confirmaste.</p><B :href="`/presupuestos/${record.accepted_budget_version_id}`" variant="secondary">Consultar presupuesto</B></v-card></aside></div></template>
        <v-dialog :model-value="!!decision" max-width="560" @update:model-value="decision = $event ? decision : ''"><div class="synaux-app"><v-card class="card modal-card"><button class="modal-close" aria-label="Cerrar" @click="decision = ''">×</button><p class="eyebrow">Confirmar decisión</p><h2>{{ decision === 'accepted' ? '¿Aceptás este presupuesto?' : '¿Querés rechazarlo?' }}</h2><p>{{ decision === 'accepted' ? 'Se creará un proyecto con esta versión y sus condiciones.' : 'La versión quedará rechazada en tu historial.' }}</p><p><strong>{{ record.title }} · {{ money(record.total,record.currency_code) }}</strong></p><p v-if="decideForm.errors.confirmed" class="error" role="alert">{{ decideForm.errors.confirmed }}</p><label class="select-row"><input v-model="decideForm.confirmed" type="checkbox">Revisé el alcance, el total, los plazos y las condiciones.</label><div class="form-actions"><B variant="secondary" @click="decision = ''">Volver</B><B :disabled="!decideForm.confirmed || decideForm.processing" @click="decide">{{ decision === 'accepted' ? 'Confirmar aceptación' : 'Confirmar rechazo' }}</B></div></v-card></div></v-dialog>
    </section>
</template>

